from typing import Any
from kopilogs.paint import paint
from dataclasses import dataclass

class Log:
    enabled = True
    icons = False

    @dataclass
    class _Information:
        type: str
        icon: str
        color: str

    def __init__(
        self,
        text: str,
        force_log: bool = False,
        force_icon: bool = False,
        tabs: int = 0,
        new_lines: int = 0,
    ):
        self.text = text
        self.force_log = force_log
        self.force_icon = force_icon

        self.tabs = ""
        for _ in range(tabs):
            self.tabs += "\t"

        self.new_lines = ""
        for _ in range(new_lines):
            self.new_lines += "\n"

    def error(self):
        self._log(Log._Information("ERROR", "*", "red"))

    def info(self):
        self._log(Log._Information("INFO", "+", "blue"))

    def warning(self):
        self._log(Log._Information("WARNING", "!", "yellow"))

    def success(self):
        self._log(Log._Information("SUCCESS", "&", "green"))

    def unknown_error(self):
        self._log(Log._Information("UNKNOWN ERROR", "?", "magenta"))

    def _log(self, information: _Information):
        log_enable_backup = Log.enabled
        log_icon_backup = Log.icons

        if self.force_log:
            Log.enabled = True
        if self.force_icon:
            Log.icons = True

        if Log.enabled and Log.icons:
            paint(
                f"{self.new_lines}{self.tabs}[", getattr(paint(information.icon).bold(), information.color)() , "] ",
                self.text,
                sep="",
            ).show()
    
        elif Log.enabled and not Log.icons:
            paint(
                f"{self.new_lines}{self.tabs}[", getattr(paint(information.type).bold(), information.color)() , "] ",
                self.text,
                sep="",
            ).show()

        Log.enabled = log_enable_backup
        Log.icons = log_icon_backup
